// Names extracted from Hassan Heshmat's autobiography for the Memoir page.
// memoir.json is generated by docs/autobiography/build_site_data.py; do not
// edit it by hand — the README there describes the whole pipeline.
import data from './memoir.json';
// The book's text behind each name, fetched only when a reader opens a passage.
import passagesUrl from './memoir-passages.json?url';

export type MemoirType = 'person' | 'place' | 'organisation' | 'artwork' | 'exhibition';
export type PlaceLevel = 'country' | 'region' | 'city' | 'district' | 'street' | 'site';

export interface MemoirEntity {
	id: string;
	type: MemoirType;
	/** English or established Latin form, normalised by the model. */
	name: string;
	nameAr: string;
	/** How often the book names it. */
	mentions: number;
	/** Printed pages of the book. */
	pages: number[];
	/** People only. */
	description?: string;
	/** A site record ("artwork:3", "residence:4", "person:<slug>"). */
	record?: string;
	years?: number[];
	level?: PlaceLevel;
	lat?: number;
	lng?: number;
	/** OpenStreetMap object the coordinates come from ("relation/123"). */
	osm?: string;
}

/** One paragraph that names an entity. */
export interface MemoirPassage {
	/** Paragraph id. */
	p: string;
	/** Where the forms of the name stand in its text: [start, end) offsets, in order. */
	marks: [number, number][];
	/** Forms the extraction quoted from this paragraph that its text does not hold. */
	missing: string[];
}

export interface MemoirPassages {
	/** Section headings, in Arabic. */
	sections: Record<string, string>;
	/** The uncorrected OCR text of each paragraph a passage points to. */
	paragraphs: Record<string, { section: string; pages: number[]; text: string }>;
	/** Each entity's passages, in the book's order. */
	entities: Record<string, MemoirPassage[]>;
}

let passages: Promise<MemoirPassages> | undefined;
export function loadPassages(): Promise<MemoirPassages> {
	passages ??= fetch(passagesUrl).then((response) => {
		if (!response.ok) throw new Error(`${response.status} ${passagesUrl}`);
		return response.json() as Promise<MemoirPassages>;
	});
	// A failed request (offline, say) is tried again on the next opening.
	passages.catch(() => (passages = undefined));
	return passages;
}

export const memoirBook = data.book;
export const memoirMethod = data.method;
export const memoirCounts = data.counts as Record<MemoirType, number>;
export const memoirEntities = data.entities as MemoirEntity[];

/** Levels drawn as points; countries and regions are listed instead. */
export const MAPPED_LEVELS: ReadonlySet<PlaceLevel> = new Set([
	'city',
	'district',
	'street',
	'site'
]);

export function ofType(type: MemoirType): MemoirEntity[] {
	return memoirEntities.filter((entity) => entity.type === type);
}

/** "p. 7", "pp. 7, 9, 12", "pp. 7, 9, 12, 14, 18 and 6 more". */
export function pageLabel(pages: number[], shown = 5): string {
	if (!pages.length) return '';
	const head = pages.slice(0, shown).join(', ');
	const rest = pages.length - shown;
	return `${pages.length === 1 ? 'p.' : 'pp.'} ${head}${rest > 0 ? ` and ${rest} more` : ''}`;
}

/** "3 mentions · pp. 7, 9, 12", without the separator when no printed page is known. */
export function mentionLabel(entity: Pick<MemoirEntity, 'mentions' | 'pages'>, shown = 5): string {
	const count = `${entity.mentions} ${entity.mentions === 1 ? 'mention' : 'mentions'}`;
	const pages = pageLabel(entity.pages, shown);
	return pages ? `${count} · ${pages}` : count;
}
